var i=`0242-stifado`;var a=`world-0242`;var n=`GR`;var s=`southern-europe`;var o=4;var r=127;var l={en:`Stifado`,ua:`Стіфадо`};var d={en:`A traditional Greece dish made with beef chuck, pearl onion, garlic, tomato passata. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: яловича лопатка, перлова цибуля, часник, томатна пасата. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,650,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`pearl-onion`,320,`g`],[`garlic`,4,`clove`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 105 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 105 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:105,i:[[`dry-red-wine`,240,`ml`],[`tomato-passata`,240,`g`],[`bay-leaf`,2,`leaf`],[`ceylon-cinnamon`,1,`pcs`],[`allspice-berries`,4,`pcs`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:i,id:a,country:`GR`,region:s,servings:4,minutes:127,title:l,text:d,steps:u};export{n as country,g as default,a as id,r as minutes,s as region,o as servings,i as slug,u as steps,d as text,l as title};